package com.vandorlabs.neoforge.canopy;

import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;

/** Actual Survival item calls; rendering, outside targeting and harvest are separate stages. */
final class CanopyItemHostChecks {
    private static int checks,profiles,fault,stages;private static String context;private static final BlockPos CLICKED=new BlockPos(8,80,8),SAVED_CLICK=new BlockPos(40,238,40),SAVED_ROOT=SAVED_CLICK.above().west().north();
    static final class FaultItem extends NativeCanopyItem {
        FaultItem(NativeCanopyBlock block){super(block,new Item.Properties());}
        @Override protected boolean stage(Level level,BlockPos pos,BlockState state){stages++;if(stages==2&&(fault==1||fault==4)||stages==3&&fault==5)return false;if(stages==2&&fault==2)throw new IllegalStateException("Injected Canopy helper write failure");return super.stage(level,pos,state);}
        @Override protected NativeCanopyEntity ownerAt(Level level,BlockPos pos){if(stages==2&&fault==3){level.removeBlockEntity(pos);return null;}return super.ownerAt(level,pos);}
        @Override protected boolean restore(Level level,BlockPos pos,BlockState old){return fault!=4&&fault!=5&&super.restore(level,pos,old);}
    }
    private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Canopy item "+context+" "+text);}
    private static BlockPos point(JsonArray p){return new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt(),p.get(2).getAsInt());}
    private static net.neoforged.neoforge.common.util.FakePlayer actor(ServerLevel world){var player=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("a8a166ec-43e9-4608-a44b-9ab357d1994e"),"CanopyItems"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.getInventory().selected=0;return player;}
    private static ItemStack held(String kind,CompoundTag tag){var stack=new ItemStack(CanopyHostChecks.block(kind),2);if(tag!=null)stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag.copy()));return stack;}
    private static InteractionResult use(ServerLevel world,net.neoforged.neoforge.common.util.FakePlayer player,BlockPos clicked,Direction facing,Direction side,ItemStack stack){player.setYRot(facing.toYRot());player.setPos(clicked.getX()+.5,clicked.getY()+1,clicked.getZ()+2);player.setItemInHand(InteractionHand.MAIN_HAND,stack);stages=0;return player.gameMode.useItemOn(player,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(clicked.getX()+.25,clicked.getY()+.75,clicked.getZ()+.625),side,clicked,false));}
    private static void configured(ServerLevel world,net.neoforged.neoforge.common.util.FakePlayer player)throws Exception {
        Set<BlockPos> previous=new HashSet<>();int cases=0,quarantined=0;try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_CANOPY_CONFIGURED_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);previous.clear();world.setBlock(CLICKED,Blocks.STONE.defaultBlockState(),18);var row=JsonParser.parseString(line).getAsJsonObject();String kind=row.get("id").getAsString();int profile=row.get("profile").getAsInt();context="configured/"+kind+"/"+row.get("playerFacing")+"/"+row.get("side")+"/"+profile;BlockPos foreign=row.has("foreign")?point(row.getAsJsonArray("foreign")):null;if(foreign!=null){world.getChunkAt(foreign);world.setBlock(foreign,Blocks.STONE.defaultBlockState(),18);previous.add(foreign);}var input=row.get("input");var stack=held(kind,input==null||input.isJsonNull()?null:CanopySettingsChecks.tags(input.getAsJsonObject()));var original=stack.copy();boolean unsupported=profile==8&&NativeCanopyModels.builtin().dimensions(kind).width()*3>9;boolean expected=row.get("result").getAsString().equals("SUCCESS")&&!unsupported;var result=use(world,player,CLICKED,Direction.from3DDataValue(row.get("playerFacing").getAsInt()),Direction.from3DDataValue(row.get("side").getAsInt()),stack);need(result.consumesAction()==expected,"configured actual Survival admission="+result);need(stack.getCount()==(expected?1:2)&&ItemStack.isSameItemSameComponents(stack,original),"configured held owner/NBT");need(world.getBlockState(CLICKED).is(Blocks.STONE)&&(foreign==null||world.getBlockState(foreign).is(Blocks.STONE)),"configured foreign/support retention");if(unsupported)quarantined++;
            if(expected){var pos=point(row.getAsJsonArray("root"));previous.add(pos);var owner=NativeCanopyLifecycle.at(world,pos);need(owner!=null,"configured root");var saved=owner.saveWithoutMetadata(world.registryAccess());saved.remove("NativeCanopySchema");saved.putString("id","vandorlabs:canopy");if(profile==12){need(saved.getString("ForeignCanopyData").equals("opaque-original"),"extra retained");saved.remove("ForeignCanopyData");}need(saved.equals(CanopySettingsChecks.tags(row.getAsJsonObject("saved"))),"configured actual Source saved owner");for(var rawCell:row.getAsJsonArray("cells")){var cell=point(rawCell.getAsJsonObject().getAsJsonArray("pos"));previous.add(cell);need(NativeCanopyLifecycle.at(world,cell)!=null,"configured installed cell");}}cases++;
        }}for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);need(cases==2112&&quarantined==36,"configured coverage");System.out.println("[vandorlabs][canopy-item-host] configured="+cases+" quarantinedRoles="+quarantined);
    }
    static void run(ServerLevel world)throws Exception {
        var player=actor(world);Set<BlockPos> previous=new HashSet<>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunkAt(CLICKED.offset(x*16,0,z*16));for(var pos:BlockPos.betweenClosed(CLICKED.offset(-12,-12,-12),CLICKED.offset(12,12,12)))world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);
        try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_CANOPY_PLACEMENT_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);previous.clear();world.setBlock(CLICKED,Blocks.STONE.defaultBlockState(),18);var row=JsonParser.parseString(line).getAsJsonObject();String kind=row.get("id").getAsString();context=kind+"/"+row.get("playerFacing")+"/"+row.get("side")+"/"+row.get("profile");var raw=row.get("input");var stack=held(kind,raw==null||raw.isJsonNull()?null:CanopySettingsChecks.tags(raw.getAsJsonObject()));var result=use(world,player,CLICKED,Direction.from3DDataValue(row.get("playerFacing").getAsInt()),Direction.from3DDataValue(row.get("side").getAsInt()),stack);boolean expected=row.get("result").getAsString().equals("SUCCESS");need(result.consumesAction()==expected,"actual Survival admission result="+result+" expectedRoot="+(row.getAsJsonObject("placed").has("root")?world.getBlockState(point(row.getAsJsonObject("placed").getAsJsonArray("root"))):"none"));need(stack.getCount()==row.get("remaining").getAsInt(),"exact single consumption");var placed=row.getAsJsonObject("placed");for(var rawCell:placed.getAsJsonArray("cells")){var cell=rawCell.getAsJsonObject();var pos=point(cell.getAsJsonArray("pos"));previous.add(pos);var owner=NativeCanopyLifecycle.at(world,pos);need(owner!=null&&owner.kind().equals(kind)&&owner.facing().get3DDataValue()==cell.get("facing").getAsInt(),"installed member");need(owner.links().anchor().equals(point(cell.getAsJsonArray("anchor"))),"configured constituent anchor");}
            if(expected){var root=NativeCanopyLifecycle.at(world,point(placed.getAsJsonArray("root")));var actual=root.saveWithoutMetadata(world.registryAccess());actual.remove("NativeCanopySchema");actual.putString("id","vandorlabs:canopy");need(actual.equals(CanopySettingsChecks.tags(placed.getAsJsonObject("saved"))),"actual Source full saved owner");}need(world.getBlockState(CLICKED).is(Blocks.STONE),"support retained");profiles++;
        }}for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);need(profiles==1056,"Source item callbacks");
        configured(world,player);context="rollback faults";var block=CanopyHostChecks.block("canopy");for(int mode=1;mode<=5;mode++){for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)world.setBlock(CLICKED.offset(x,1,z),Blocks.AIR.defaultBlockState(),18);world.setBlock(CLICKED,Blocks.STONE.defaultBlockState(),18);fault=mode;var stack=held(mode==5?"long_canopy":"canopy",null);boolean threw=false;try{use(world,player,CLICKED,Direction.SOUTH,Direction.UP,stack);}catch(RuntimeException injected){threw=true;need(mode==2,"unexpected staged exception");}finally{fault=0;}var root=CLICKED.above();if(mode==4||mode==5){var retained=NativeCanopyLifecycle.at(world,root);need(stack.getCount()==1&&retained!=null&&retained.inert()&&retained.recoverySnapshot().contains(NativeCanopyEntity.RECOVERY,Tag.TAG_COMPOUND),"rollback refusal retains exactly one inert data owner");}else{need(stack.getCount()==2,"failed helper installs retain held owner mode="+mode);need(world.isEmptyBlock(root),"failed placement root rolled back mode="+mode);}if(mode==2)need(threw,"original exception diagnostics preserved");}
        context="configured process restart";world.getChunkAt(SAVED_CLICK);world.setBlock(SAVED_CLICK,Blocks.STONE.defaultBlockState(),18);var tag=new CompoundTag();tag.putInt("CanopyDepth",17);var generic=new CompoundTag();generic.putInt("CanopyDepth",42);tag.put("BlockEntityTag",generic);var stack=held("front_canopy_glass",tag);need(use(world,player,SAVED_CLICK,Direction.NORTH,Direction.UP,stack).consumesAction()&&stack.getCount()==1,"configured placed saved owner");var root=NativeCanopyLifecycle.at(world,SAVED_ROOT);need(root!=null&&root.settings().data().depth==17,"canonical outer precedence");System.out.println("[vandorlabs][canopy-item-host] PASS SourceCallbacks="+profiles+" checks="+checks);
    }
    static void read(ServerLevel world){context="item separate-process read";world.getChunkAt(SAVED_ROOT);var root=NativeCanopyLifecycle.at(world,SAVED_ROOT);need(root!=null&&root.settings().data().depth==17&&root.links().anchor().equals(SAVED_ROOT),"one configured owner after process restart");world.getChunkAt(CLICKED.above());var recovery=NativeCanopyLifecycle.at(world,CLICKED.above());need(recovery!=null&&recovery.inert()&&recovery.recoverySnapshot().contains(NativeCanopyEntity.RECOVERY,Tag.TAG_COMPOUND),"rollback-refused owner remains inert with original data after restart");}
}
